function loadSave(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(s){if(Array.isArray(s.progress)&&s.progress.length===3)progress=s.progress.map(n=>THREE.MathUtils.clamp(Math.floor(Number(n)||0),0,3));if(Number.isFinite(s.money))money=Math.max(0,s.money);if(Number.isInteger(s.activeHero)&&s.activeHero>=0&&s.activeHero<3)activeHero=s.activeHero;if(typeof s.activeMapId==='string'&&mapCatalog?.getMapRegion?.(s.activeMapId))activeMapId=s.activeMapId;if(typeof s.activeSideStoryId==='string'&&sideStories?.SIDE_STORIES?.some(story=>story.id===s.activeSideStoryId))activeSideStoryId=s.activeSideStoryId;if(sideStories?.normalizeSideStoryProgress)sideStoryProgress=sideStories.normalizeSideStoryProgress(s.sideStoryProgress);if(Array.isArray(s.decisions)&&s.decisions.length===3)decisions=s.decisions.map(row=>[0,1,2].map(i=>row?.[i]===0||row?.[i]===1?row[i]:null));if(Array.isArray(s.collectedRelics))collectedRelics=[...new Set(s.collectedRelics.filter(n=>Number.isInteger(n)&&n>=0&&n<12))];if(Array.isArray(s.completedContracts))completedContracts=[...new Set(s.completedContracts.filter(n=>Number.isInteger(n)&&n>=0&&n<contractRoutes.length))];if(Array.isArray(s.discoveredDistricts))s.discoveredDistricts.filter(n=>typeof n==='string'&&zones.some(z=>z.name===n)).forEach(n=>discoveredDistricts.add(n));if(s.garageUpgrades&&typeof s.garageUpgrades==='object')for(const key of ['engine','handling','armor'])garageUpgrades[key]=THREE.MathUtils.clamp(Math.floor(Number(s.garageUpgrades[key])||0),0,3);if(s.graphicsSettings&&typeof s.graphicsSettings==='object')graphicsSettings={...graphicsSettings,...s.graphicsSettings};if(Array.isArray(s.completedServices))completedServices=[...new Set(s.completedServices.filter(n=>n==='ARTS CORNER CAFE'))];if(typeof s.selectedVehicle==='string'&&['SPORT','SEDAN','SUV'].includes(s.selectedVehicle))selectedVehicle=s.selectedVehicle;if(typeof s.audioMuted==='boolean')audioMuted=s.audioMuted;graphicsSettings.quality=['PERFORMANCE','HIGH','ULTRA','EXTREME'].includes(graphicsSettings.quality)?graphicsSettings.quality:'HIGH';graphicsSettings.atmosphere=['DAYLIGHT','GOLDEN HOUR','NEON NIGHT'].includes(graphicsSettings.atmosphere)?graphicsSettings.atmosphere:'GOLDEN HOUR';graphicsSettings.volume=THREE.MathUtils.clamp(Number(graphicsSettings.volume)||0,0,100);graphicsSettings.reducedMotion=graphicsSettings.reducedMotion===true;}}catch(e){console.warn('Save data could not be loaded',e)}}
function saveGame(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({version:9,progress,money,activeHero,activeMapId,activeSideStoryId,sideStoryProgress,decisions,collectedRelics,completedContracts,discoveredDistricts:[...discoveredDistricts],garageUpgrades,graphicsSettings,selectedVehicle,completedServices,audioMuted,updatedAt:Date.now()}));setText('save-status','SAVED')}catch(e){setText('save-status','SESSION ONLY')}}

const garagePanel=document.querySelector('#garage-panel');
