function initAudio(){if(!audioEnabled||audioContext)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioContext=new AC();engineOsc=audioContext.createOscillator();engineOsc.type='sawtooth';engineGain=audioContext.createGain();engineGain.gain.value=.0001;engineOsc.connect(engineGain);engineGain.connect(audioContext.destination);engineOsc.start();skidOsc=audioContext.createOscillator();skidOsc.type='triangle';skidGain=audioContext.createGain();skidGain.gain.value=.0001;skidOsc.connect(skidGain);skidGain.connect(audioContext.destination);skidOsc.start()}catch(e){console.warn('Audio unavailable',e)}}
