const journalPanel=document.querySelector('#journal-panel');
function renderJournal(){const host=document.querySelector('#journal-content');if(!host)return;const summary=document.createElement('p');summary.className='journal-summary';summary.textContent='CASH $'+money+' · RELICS '+collectedRelics.length+'/12 · CONTRACTS '+completedContracts.length+'/'+contractRoutes.length+' · DISTRICTS '+discoveredDistricts.size+'/'+zones.length;const cards=storyData.map((hero,index)=>{const card=document.createElement('article');card.className='journal-card';const heading=document.createElement('h3');heading.textContent=hero.name+(index===activeHero?' · ACTIVE':'');const status=document.createElement('p');status.textContent=progress[index]===3?'CHAPTER COMPLETE':progress[index]+'/3 STORY BEATS COMPLETE';const list=document.createElement('ul');hero.missions.forEach((mission,missionIndex)=>{const item=document.createElement('li');const choice=decisions[index][missionIndex];const state=missionIndex<progress[index]?'COMPLETE':missionIndex===progress[index]?'CURRENT':'LOCKED';item.className=missionIndex<progress[index]?'complete':missionIndex===progress[index]?'current':'';item.textContent=mission.title+' · '+state+(choice===0?' · CHOICE A':choice===1?' · CHOICE B':'');list.append(item)});card.append(heading,status,list);return card});const sideCards=(sideStories?.SIDE_STORIES||[]).map(story=>{const state=sideStoryProgress[story.id]||{step:0,completed:false,choices:[]};const card=document.createElement('article');card.className='journal-card';const heading=document.createElement('h3');heading.textContent=story.title+(activeSideStoryId===story.id?' · ACTIVE':'');const status=document.createElement('p');status.textContent=state.completed?'SIDE STORY COMPLETE':state.step+'/3 SIDE STORY BEATS COMPLETE';const list=document.createElement('ul');story.missions.forEach((mission,index)=>{const item=document.createElement('li');item.textContent=mission.title+' · '+(index<state.step?'COMPLETE':index===state.step&&!state.completed?'CURRENT':'LOCKED');list.append(item)});card.append(heading,status,list);return card});host.replaceChildren(summary,...cards,...sideCards)}
function toggleJournal(force){if(!journalPanel)return;const open=typeof force==='boolean'?force:journalPanel.hidden;if(open&&(paused||dialogue||driving)){say('Open the journal while on foot and outside dialogue');return}journalPanel.hidden=!open;document.querySelector('#journal-toggle')?.setAttribute('aria-expanded',String(open));if(open){keys={};document.exitPointerLock?.();renderJournal()}}
