function buildCityServices(){
 for(const service of cityServices){
  const g=new THREE.Group();g.position.set(service.x,0,service.z);city.add(g);
  const base=mat('#202735',.68,.18),accent=new THREE.MeshStandardMaterial({color:service.color,emissive:service.color,emissiveIntensity:.7,roughness:.42});
  box(g,10,5,7,base,0,2.5,0);box(g,10.5,.45,7.5,accent,0,5.2,0,false);
  box(g,6,1.35,.16,base,0,3.8,3.58,false);
  const signCanvas=document.createElement('canvas');signCanvas.width=512;signCanvas.height=128;const ctx=signCanvas.getContext('2d');ctx.fillStyle='#111522';ctx.fillRect(0,0,512,128);ctx.fillStyle=service.color;ctx.font='bold 38px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(service.name,256,64);const texture=new THREE.CanvasTexture(signCanvas);texture.colorSpace=THREE.SRGBColorSpace;const sign=new THREE.Mesh(new THREE.PlaneGeometry(5.8,1.25),new THREE.MeshBasicMaterial({map:texture,transparent:false}));sign.position.set(0,3.8,3.68);g.add(sign);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(4,.12,8,32),accent);ring.rotation.x=Math.PI/2;ring.position.y=.16;g.add(ring);
  serviceMarkers.push({...service,group:g,ring});
 }
}
buildCityServices();
function nearestCityService(){let best=null,bestDistance=8;for(const service of serviceMarkers){const d=Math.hypot(player.position.x-service.x,player.position.z-service.z);if(d<bestDistance){best=service;bestDistance=d}}return best}
function useCityService(service){
 if(!service)return;
 if(service.kind==='repair'){
  if(carHealth>=maxCarHealth()){say('KOLKATA MOTOR WORKS · Your vehicle is already in top condition');return}
  if(money<100){say('KOLKATA MOTOR WORKS · REPAIR COSTS $100 · NOT ENOUGH CASH');return}
  carHealth=maxCarHealth();setText('car-health','100%');const fill=document.querySelector('#car-health-fill');if(fill)fill.style.width='100%';document.querySelector('#vehicle-hud')?.classList.remove('low-health');money-=100;playUiCue('service');say('KOLKATA MOTOR WORKS · VEHICLE RESTORED · SERVICE $100');
 }else if(service.kind==='fuel'){
  nitroFuel=100;setText('nitro-value','100%');const fill=document.querySelector('#nitro-fill');if(fill)fill.style.width='100%';playUiCue('service');say('PALM FUEL & MARKET · NITRO REFILLED');
 }else if(service.kind==='customs'){
  if(selectedVehicle==='SPORT'){say('NEON CUSTOMS · Your sports coupe is already tuned');return}
  selectedVehicle='SPORT';replacePlayerVehicle();playUiCue('service');say('NEON CUSTOMS · SPORTS COUPE SELECTED');
 }else{
  if(completedServices.includes(service.name)){say('ARTS CORNER CAFE · Thanks for visiting again');return}
  completedServices.push(service.name);money+=75;playUiCue('service');say('ARTS CORNER CAFE · Thanks for stopping by · +$75');
 }
 syncUI();saveGame();
}
function collectRelic(r){if(!r||r.collected)return;r.collected=true;collectedRelics.push(r.id);r.group.visible=false;playUiCue('pickup');const reward=150;money+=reward;setText('cash','$'+money);setText('relic-count',collectedRelics.length+' / 12');saveGame();say('NEON RELIC FOUND · +$'+reward+' · '+collectedRelics.length+'/12');if(collectedRelics.length===12){money+=1000;setText('cash','$'+money);saveGame();say('ALL 12 RELICS FOUND · BONUS +$1000')}}
function buildRelics(){const spots=[[0,42],[42,0],[-42,0],[0,-42],[84,0],[-84,42],[42,84],[-126,0],[126,84],[84,-84],[-84,-126],[168,0]];spots.forEach(([x,z],id)=>{const g=new THREE.Group();g.position.set(x,.9,z);const gemMat=new THREE.MeshStandardMaterial({color:'#65f3e4',emissive:'#21d9ce',emissiveIntensity:1.35,metalness:.45,roughness:.22});const gem=new THREE.Mesh(new THREE.OctahedronGeometry(.72,0),gemMat);gem.rotation.y=Math.PI/4;g.add(gem);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.12,.055,8,28),new THREE.MeshBasicMaterial({color:'#7df9ed',transparent:true,opacity:.88}));ring.rotation.x=Math.PI/2;g.add(ring);const halo=new THREE.Mesh(new THREE.SphereGeometry(1.35,12,8),new THREE.MeshBasicMaterial({color:'#26e8d9',transparent:true,opacity:.08,depthWrite:false}));g.add(halo);scene.add(g);const collected=collectedRelics.includes(id);g.visible=!collected;relics.push({id,x,z,group:g,gem,ring,collected})})}
