 if(carHealth<=0){say('The sports car is disabled · press R at a checkpoint to repair it');return}if(Math.hypot(player.position.x-playerCar.position.x,player.position.z-playerCar.position.z)>5.5){say('Move closer to the gold sports car to drive it · F');return}
 driving=true;avatar.visible=false;player.position.copy(playerCar.position);initAudio();say('Vehicle entered · WASD drive · SPACE handbrake · F exit'); 
