function startInteraction(){if(paused)return;if(driving){say('Exit the vehicle with F before starting a story interaction');return}if(dialogue){if(dialogue.choosing)return;dialogue.index++;if(dialogue.index>=dialogue.lines.length){dialogue.choosing=true;showDialogue();return}showDialogue();return}const relic=nearestRelic();if(relic){collectRelic(relic);return}const m=currentMission();if(m&&closeToMission()){dialogue={index:0,lines:m.lines,speaker:m.speaker,hero:activeHero,missionIndex:progress[activeHero],sideStoryId:activeSideStoryId,sideMissionIndex:activeSideStoryId?(sideStoryProgress[activeSideStoryId]?.step||0):null,choices:m.choices||null,choosing:false};showDialogue();return}const nearbyService=nearestCityService();if(nearbyService){useCityService(nearbyService);return}const nearbyPed=nearestPedestrian();if(nearbyPed){talkToPedestrian(nearbyPed);return}if(!m){say('This chapter is complete. Switch protagonists for another story.');return}say('Move closer to the glowing story marker.')}
