function applyGraphicsQuality(){document.documentElement.dataset.graphicsQuality=graphicsQuality;const profiles={PERFORMANCE:{ratio:1,shadow:768,exposure:1.08,fog:.0034,dust:false},HIGH:{ratio:1.35,shadow:1536,exposure:1.12,fog:.0031,dust:false},ULTRA:{ratio:1.7,shadow:2048,exposure:1.15,fog:.0029,dust:true},EXTREME:{ratio:2,shadow:3072,exposure:1.18,fog:.0027,dust:true}};const p=profiles[graphicsQuality]||profiles.HIGH;currentGraphicsProfile=p;adaptiveScale=1;renderer.setPixelRatio(Math.min(devicePixelRatio||1,p.ratio));renderer.setSize(root.clientWidth,root.clientHeight);sun.shadow.mapSize.setScalar(p.shadow);sun.shadow.needsUpdate=true;renderer.shadowMap.enabled=graphicsQuality!=='PERFORMANCE';renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMappingExposure=p.exposure;effects?.setQuality(graphicsQuality);effects?.resize();scene.fog.density=p.fog;atmosphericDust.visible=p.dust&&!graphicsSettings.reducedMotion;hazeMaterial.opacity=graphicsQuality==='EXTREME'?.32:.22;setText('graphics-toggle','GRAPHICS · '+graphicsQuality)}document.querySelector('#graphics-toggle')?.addEventListener('click',()=>{graphicsQuality=graphicsQuality==='HIGH'?'ULTRA':graphicsQuality==='ULTRA'?'EXTREME':graphicsQuality==='EXTREME'?'PERFORMANCE':'HIGH';graphicsSettings.quality=graphicsQuality;applyGraphicsQuality();saveGame();say('Graphics preset: '+graphicsQuality)});applyGraphicsQuality();syncCameraZoomLabel();
